INSERT INTO `erp_department` (`id`, `kics_id`, `campus_id`, `parent_department_id`, `name`, `complete_name`, `parent_department`, `manager`, `campus`, `active`, `is_visible`, `admin_notes`, `dept_code`, `dept_type`, `department_type`, `web_department_name`, `web_detail_description`, `vision`, `mission`, `logo`, `cover_image`, `appraisals_to_process`, `created_at`, `updated_at`) VALUES
(1, 2, 1, 22, 'Accounts', 'Al-Khwarizmi Institute of Computer Science / Accounts', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Muhammad Ismaeel (Accounts Manager)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 0, NULL, 'Accounts', 'Offices', 'Directorate', '', '<p>The office manages the accounts and finance operations of the institute</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-09-24 23:35:11'),
(2, 1, 1, 22, 'Administration', 'Al-Khwarizmi Institute of Computer Science / Administration', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Aqeel Muhammad Babar (Sr. Manager Procurement)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 0, NULL, 'ADMIN', 'Offices', 'Directorate', '', '<p>The office manages the administrative operations of the institute</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-08-17 02:10:12'),
(3, 62, 1, 22, 'Agriculture Technology Research Lab', 'Al-Khwarizmi Institute of Computer Science / Agriculture Technology Research Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Prof. Dr. Muhammad Shahbaz (KICS/PI/Principal Investigator)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'ATRL', 'Academic', 'Department', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-09-29 03:17:23'),
(4, 22, 1, NULL, 'Al-Khwarizmi Institute of Computer Science', 'Al-Khwarizmi Institute of Computer Science', '', 'Dr. Hafiz Muhammad Shahzad Asif (Director)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'KICS', 'Offices', 'VP/VC Office', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-08-17 06:07:03'),
(5, 6, 1, 22, 'Alternate Energy Research and Innovation Lab', 'Al-Khwarizmi Institute of Computer Science / Alternate Energy Research and Innovation Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Imran Ali Shah (Principal Manager)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'AERIL', 'Academic', 'Department', '', '<p>AERIL focuses on research and innovation in the areas of renewable energy technologies (solar, wind, fuel cell etc), energy optimization, testing and certification, sustainable energy efficient development, and alternate energy based home and office appliances.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(6, 71, 1, 22, 'Audit', 'Al-Khwarizmi Institute of Computer Science / Audit', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 0, NULL, 'Audit', 'Offices', 'Directorate', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-08-17 01:22:07'),
(7, 7, 1, 22, 'Bioinformatics Research Lab', 'Al-Khwarizmi Institute of Computer Science / Bioinformatics Research Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. M.Usman Ghani Khan (ICRL/PTE/Consultant Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'BRL', 'Offices', 'Directorate', '', '<p>he Bioinformatics Laboratory at KICS, U.E.T. Lahore was established using the starter grant from HEC, Pakistan. This laboratory has been catering for the local needs at the university level. In the near future, the Lab aims to provide a national bioinformatics information network designed to cater for the inter-disciplinary and collaborative research needs of the research/scientific community and the industry</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(8, 36, 1, 22, 'CERAD', 'Al-Khwarizmi Institute of Computer Science / CERAD', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'CERAD', 'Offices', 'Directorate', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(9, 8, 1, 22, 'Center for Language Engineering', 'Al-Khwarizmi Institute of Computer Science / Center for Language Engineering', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Ms. Sana Shams (CLE/CEC/Principal Manager)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'CLE', 'Offices', 'Directorate', '', '<p>Center for Language Engineering (CLE) is conducting research and development in linguistic and computational aspects of languages, specifically of Pakistan and developing Asia. The center also actively arranges and participates in seminars, workshops and conferences dedicated to promote language processing nationally and internationally. This work will be instrumental in development of computing in relevant languages.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(10, 9, 1, 22, 'Computer Vision and Machine Learning Lab', 'Al-Khwarizmi Institute of Computer Science / Computer Vision and Machine Learning Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. M.Usman Ghani Khan (ICRL/PTE/Consultant Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'CVML', 'Offices', 'Directorate', '', '<p>Computer Vision and Machine Learning (CVML) Lab at Al-Khwarizmi Institute of Computer Sciences focuses on the research and development of image processing tools, computer vision algorithms, natural language processing and applications helpful to community from the field of computer vision. Dedicated research staff comprising 2 PHDs and over 10 full-time research officers and undergraduate/postgraduate interns, the lab is involved in the development of core APIs required for the surveillance systems including face recognition, emotions and actions recognition and scene settings.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(11, 60, 1, 22, 'DFKI', 'Al-Khwarizmi Institute of Computer Science / DFKI', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'DFKI', 'Academic', 'Department', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(12, 61, 1, 22, 'DFKI LAB', 'Al-Khwarizmi Institute of Computer Science / DFKI LAB', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'DFKI LAB', 'Academic', 'Department', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(13, 10, 1, 22, 'Data Science Lab', 'Al-Khwarizmi Institute of Computer Science / Data Science Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. M.Usman Ghani Khan (ICRL/PTE/Consultant Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'DSL', 'Offices', 'Directorate', '', '<p>Data Science Lab was established in 2017 to cater the challenges of current age which may be termed as the era of \"data big bang\". Driven by the internet economy, mobile phone, cheaper hardware and the Internet of Things (IoT), the user and other sensory devices are continuously generating a lot of data. As data size increases, the demand for multi scale approaches in transforming data to knowledge also becomes very important. \nResearch in DSL involves the design of intelligent algorithms and development of decision-making models to form risk management systems and process modeling systems. Interpreting data and visualizing it to define patterns and extract knowledge can help businesses to compete with other competitors. The lab focuses on both the structured and unstructured data analytics for clustering, classification, and association rule mining to identify trends and make useful predictions.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(14, 54, 1, 22, 'EV Lab', 'Al-Khwarizmi Institute of Computer Science / EV Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'EVL', 'Academic', 'Department', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(15, 11, 1, 22, 'Energy Efficiency and Conservation Lab', 'Al-Khwarizmi Institute of Computer Science / Energy Efficiency and Conservation Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Muhammad Ali (Principal Manager )', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'EECL', 'Offices', 'Directorate', '', '<p>The lab performs domestic, commercial and industrial energy audits, provides hands on training to Engineers and Diploma holders, continue and sustain \"Energy Efficiency Advisor\" Program in collaboration with GIZ and Sequa. The lab also provides support in establishing other facilities related to Motor Testing and Air Conditioner Unit Testing and Labeling.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(16, 12, 1, 22, 'Enterprise Software Solution Lab', 'Al-Khwarizmi Institute of Computer Science / Enterprise Software Solution Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Ali Muzaffar (Manager Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'ESSL', 'Offices', 'Directorate', '', '<p>Enterprise Software Solution (ESS) Lab formally UMS lab is a leader in its domain of providing services in Academic Management System, in KICS. Ever since its inception in 2002, it has evolved and taken center stage in information and technology by providing ERP and Non ERP solutions to the Government and Private educational sectors. With the hands-on experience and domain expertise, we have completed handsome projects in the Punjab, Pakistan. We excel at delivering business solutions outside Punjab to other University and Colleges too.What makes us distinctive is our ability to assist clients and meet challenges. We serve them to enrich their productivity by guaranteeing that their core business functions work faster, economical and better by providing them solutions in OPEN SOURCE. Considering the mind set of Pakistani users, we provide economical solutions with open source option in ERP environment so that they can take their business to the next level.ESS has proven its worth to many Universities by implementing OBE and Bloom taxonomy in their LMS Systems. Many international conferences had been hosted where it’s services and innovation has been admired.Help others achieve their dreams and you will achieve yours - Les Brown.”</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(17, 14, 1, 22, 'High Performance Computing and Networking Lab', 'Al-Khwarizmi Institute of Computer Science / High Performance Computing and Networking Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. M. Amir Mehmood (Associate Professor)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'HPCNL', 'Offices', 'Directorate', '', '<p>High performance computing (HPC) has become essential to almost every field of research to foster innovation and growth. The proliferation of cloud based applications along with the phenomenal growth in smart phone adoption has completely changed the high performance computing landscape. Today, high performance computing is reaching exascale as billions of devices generate zettabytes of IP traffic which is served from various cloud infrastructures and data centers across the globe. HPCNL was established in June 2008 to initiate R&amp;D in HPC and its related echo system. Our research lab is focused on computer systems, networks, and application performance debugging. Our aim is to use overarching approach in cloud computing by covering various aspects related to the cloud such as multi-core infrastructure, virtualization, parallel computing, and distributed application development.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(18, 16, 1, 22, 'Huawei UET Telecom and IT Center', 'Al-Khwarizmi Institute of Computer Science / Huawei UET Telecom and IT Center', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. M. Tahir Naeem (Manager Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'HUTIC', 'Offices', 'Directorate', '', '<p>UET is the pioneer in establishing state of the art HUAWEI training center, in Pakistan. UET and Huawei collaborated and took a new leap with the establishment of Huawei UET Joint Telecom IT Centre. Our center features two training facilities, one in UET and the other in P6 Model Town. HUTIC was inaugurated in 2002-03 in UET, in collaboration with Huawei Technologies. Equipment. UET offers the largest training facility in Telecom and Data Comm. technologies in the region. The agreement included NGN, Broadband, GSM/GPRS, Data Comm. and Video Conferencing products.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(19, 13, 1, 22, 'Human Centered Robotics Research Lab', 'Al-Khwarizmi Institute of Computer Science / Human Centered Robotics Research Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. Ali Raza (Principal Investigator)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'HCRL', 'Offices', 'Directorate', '', '<p>The Human-Centered Robotics Lab aims to indigenously design and develop integrated robotic systems, based on smart sensing and actuation, to seamlessly interact with humans, actively learn from them and eventually create an effective collaborative environment. In this pursuit, currently, we are developing collaborative robots, upper-body exoskeletons, and lower-body active prostheses at the University of Engineering and Technology (UET), Lahore, and lower-limb orthoses/exoskeletons at the University of Central Punjab, Lahore.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(20, 15, 1, 22, 'Human Resource', 'Al-Khwarizmi Institute of Computer Science / Human Resource', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'HR', 'Offices', 'Directorate', '', '<p>This office deals with the HR operations of the institute,</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:42', '2026-07-09 02:51:02'),
(21, 35, 1, 22, 'IC Design Lab', 'Al-Khwarizmi Institute of Computer Science / IC Design Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'ICDL', 'Offices', 'Directorate', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:02'),
(22, 17, 1, 22, 'Industrial Automation and Control Lab', 'Al-Khwarizmi Institute of Computer Science / Industrial Automation and Control Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'IACL', 'Offices', 'Directorate', '', '<p>IACL Lab has recently been established at KICS in order to develop strong linkage with local industries. The lab executes projects on turn key basis, Provide consultancy, Perform research works in developing new technologies for local market and affordable solutions for new and existing clients.The solutions cover design and integration of Instruments, Electrical and Supervisory Control and Data Acquisition (SCADA) systems, Distributed control systems (DCS), and other smaller control system configurations such as Programmable logic controllers (PLC) often found in industrial and critical infrastructures.The in-house expertise consists of Siemens and Allen-bradley PLC alongwith HMI.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:02'),
(23, 18, 1, 22, 'Industrial Collaboration Lab', 'Al-Khwarizmi Institute of Computer Science / Industrial Collaboration Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Abdullah M. Maud (Research Officer )', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'ICL', 'Offices', 'Directorate', '', '<p>This lab works with other labs for the smooth and timely delivery of the projects</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:02'),
(24, 64, 1, 22, 'Information Dissemination Lab -IDL', 'Al-Khwarizmi Institute of Computer Science / Information Dissemination Lab -IDL', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'IDL', 'Academic', 'Department', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:02'),
(25, 21, 1, 22, 'Information Technology', 'Al-Khwarizmi Institute of Computer Science / Information Technology', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. M Mudasser Khan (Consultant Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'IT', 'Offices', 'Directorate', '', '<p>This Office manages the IT sections of the institute,</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:02'),
(26, 19, 1, 22, 'Intelligent Criminology Research Lab (NCAI)', 'Al-Khwarizmi Institute of Computer Science / Intelligent Criminology Research Lab (NCAI)', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. M.Usman Ghani Khan (ICRL/PTE/Consultant Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'ICRL', 'Offices', 'Directorate', '', '<p>ICRL was established as a part of National center for artificial intellegence.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:02'),
(27, 20, 1, 22, 'IoT Research and Innovation Lab (NCCS)', 'Al-Khwarizmi Institute of Computer Science / IoT Research and Innovation Lab (NCCS)', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. Ghalib A. Shah (Principal Investigator )', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'IRIL', 'Offices', 'Directorate', '', '<p>Smart things equipped with the capability to observe and/or interact with physical environment and the ability to communicate with other things, are extending the Internet towards the so called Internet of Things (IoT). IoT has the potential to significantly influence our lives and the way we interact with the devices such as sensors, actuators, mobile phones, home automation devices, smart grid devices, etc. It has promoted concepts of flexible designs, visions and enormous applications. For individual users, IoT brings useful applications in home automation, security, automated devices monitoring and management of daily tasks. For professionals, automated applications provide useful contextual information frequently to help on their works and decision making. For Industrialists, Internet enabled sensors and actuators operations can be rapid, efficient and more economic. Managers who need to keep eye on many things can automate tasks by connecting digital and physical objects together.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:02'),
(28, 73, 1, 22, 'KICS - Projects', 'Al-Khwarizmi Institute of Computer Science / KICS - Projects', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'KICS - Projects', 'Offices', 'Directorate', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(29, 72, 1, 22, 'Learning Management System - Admissions', 'Al-Khwarizmi Institute of Computer Science / Learning Management System - Admissions', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'LMS Admission', 'Offices', 'Directorate', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(30, 23, 1, 22, 'Motion Control Research Lab', 'Al-Khwarizmi Institute of Computer Science / Motion Control Research Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'MCRL', 'Offices', 'Directorate', '', '<p>Motion Control and Research Lab (MCRL) provides research and development in field of advanced energy using efficient designing tools for designing and local resources for manufacturing of the products keeping in view the local energy needs and availability of resources. In the wake of ongoing energy crisis in Pakistan, this lab is committed to solve the energy problem by putting green and completely renewable energy generating projects to meet the industrial, agricultural and domestic demand of Pakistan. Modern designing and simulation software are used to test the product before prototype development and then prototype undergoes rigorous testing to ensure it meets the design criteria.\nMotion Control and Research Lab (MCRL) is working to come out with efficient and reliable solutions for energy crisis, for this purpose heliostats, parabolic trough and dishes are under development phases. These systems will track the sun to get maximum energy from sun and make it available for utility. On the other hand, MCRL is working on energy efficient electric vehicles. Energy efficient electric vehicles feeds lost energy back to energy source.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(31, 57, 1, 22, 'National Center of Artificial Intelligence', 'Al-Khwarizmi Institute of Computer Science / National Center of Artificial Intelligence', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. M.Usman Ghani Khan (ICRL/PTE/Consultant Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'NCAI', 'Offices', 'Section', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(32, 24, 1, 22, 'Next-Generation Wireless Networking Lab', 'Al-Khwarizmi Institute of Computer Science / Next-Generation Wireless Networking Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Hammad Hassan (Manager Research )', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'NWNL', 'Offices', 'Directorate', '', '<p>Next-generation wireless networking (NWN) lab at Al-Khawrizmi Institute of Computer Science (KICS) focuses in research and development activities in the areas of wireless sensor networks (WSN), Internet of things (IoT) and software defined networks (SDN). Comprising 3 PHDs and over 15 full-time research associates and undergraduate/postgraduate interns, the lab is involved in developing IEEE 802.15.4/802.11 compliant wireless sensor/camera node, designing and implementing communication protocols and architecture, and developing various applications.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(33, 26, 1, 22, 'Pearson VUE Testing Center', 'Al-Khwarizmi Institute of Computer Science / Pearson VUE Testing Center', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'PVUE', 'Offices', 'Directorate', '', '<p>Pearson VUE Selected Testing Center</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(34, 27, 1, 22, 'Power System Lab', 'Al-Khwarizmi Institute of Computer Science / Power System Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. Jamshaid Iqbal Janjua (Principal Manager)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'PSL', 'Offices', 'Directorate', '', '<p>This group conducts research and development activities in developing model-based and tool-supported design methodologies for real-time fault tolerant software on heterogeneous distributed platforms. We are bridging the gap between computer science and systems science by developing the foundations of a modern systems science that is simultaneously computational and physical. This represents a major departure from the current, separated structure of computer science (CS), computer engineering (CE), and electrical engineering (EE). It reintegrates information and physical sciences.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(35, 25, 1, 22, 'Professional Development Center', 'Al-Khwarizmi Institute of Computer Science / Professional Development Center', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Muhammad Zubair (Sr. Manager Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'PDC', 'Offices', 'Directorate', '', '<p>Professional Development Center (PDC-KICS) was established in August, 2016 at the University of Engineering &amp; Technology Lahore (UET), Model Town Campus for conducting research &amp; development activities and Professional Trainings in the fields of Computer Science and Information Technology. It was envisioned as an institute for advanced and high quality applied research working in collaboration with industries and other academic institutions on national and international levels to bring about the IT revolution in Pakistan and help build a knowledge driven economy.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(36, 28, 1, 22, 'School Of Media Studies', 'Al-Khwarizmi Institute of Computer Science / School Of Media Studies', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Rehan Tariq (Program Manager)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'SMS', 'Offices', 'Directorate', '', '<p>School of Media Studies (SMS), KICS UET Lahore has launched first official Web TV of UET. Web TV as a platform for reaching people all over the world. School of Media studies (SMS) is the first ever Media department of UET Lahore, running under the supervision of Al-Khwarizmi Institute of Computer Sciences (KICS) UET Lahore. It was inaugurated by Syed Raza Ali Gillani (Former Minister of Higher Education, GOVT of Punjab). SMS offers professional training courses in broadcast journalism. SMS provides an excellent environment including studios, NEWS Room and other facilities to train the students in an appropriate manner. It aims to provide trainings necessary to obtain a position and build a career in highly competitive, liberal dominated field of broadcast journalism.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(37, 29, 1, 22, 'Software Systems Research Lab', 'Al-Khwarizmi Institute of Computer Science / Software Systems Research Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Muzammil Hassan (Sr. Manager Research)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'SSRL', 'Offices', 'Directorate', '', '<p>Software Systems Research Lab (SSRL) offers software development and research services in diverse domains including web applications, enterprise systems development, prototyping, and smart-phone applications. Since 2002, the group has developed a number of solutions that implement complicated business logic and complex workflows. SSRL is currently expanding its services by engaging in research and development activities in the areas of smart-phone applications and games. Open source technologies are extensively utilized in software development in order to achieve cost and time efficiencies. SSRL also offers trianings in web application development and mobile app and game development.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(38, 30, 1, 22, 'Technology Incubation and Commercialization Center', 'Al-Khwarizmi Institute of Computer Science / Technology Incubation and Commercialization Center', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Muhammad Farhan Riaz (Program Manager )', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'TICK', 'Offices', 'Directorate', '', '<p>TICK firmly believe in changing the national and individual fortune by familiarizing and exposing students to the Entrepreneurial Ventures and Startup Culture. We do this by providing students with the required infrastructure, office space,mentoring and consultancy to nourish their ideas from infant seed stage to the flourished high growth venture. We happen to be the Technology Incubation Center by Khwarizimi Institute of Computer Sciences, UET Lahore</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(39, 31, 1, 22, 'Trainings', 'Al-Khwarizmi Institute of Computer Science / Trainings', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Mr. Kashif Bashir (Sr.Manager Training)', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'Trainings', 'Offices', 'Directorate', '', '<p>This office manages the training programs.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(40, 70, 1, 22, 'UET Services', 'Al-Khwarizmi Institute of Computer Science / UET Services', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'UET-S', 'Offices', 'Directorate', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(41, 32, 1, 22, 'Wireless System Research Lab', 'Al-Khwarizmi Institute of Computer Science / Wireless System Research Lab', 'Al-Khwarizmi Institute of Computer Science - KICS', 'Dr. Imran Javed (Consultant Research )', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'WSRL', 'Offices', 'Directorate', '', '<p>This group conducts research and development activities in wireless communication systems. The activities range from analysis and design of system level architecture to implementation of required algorithms on real-time FPGA (Field Programmable Gate Arrays) and DSP (Digital Signal Processing) development environment.</p>', '', '', NULL, NULL, '', '2026-07-02 09:33:43', '2026-07-09 02:51:03'),
(42, 74, 1, 22, 'Summer Internship - Unpaid', 'Al-Khwarizmi Institute of Computer Science / Summer Internship - Unpaid', 'Al-Khwarizmi Institute of Computer Science - KICS', '', 'Al-Khawarizmi Institute of Computer Science, UET Lahore', 1, 1, NULL, 'Summer Internship', 'Offices', 'Directorate', '', '<p><br></p>', '', '', NULL, NULL, '', '2026-08-05 02:24:22', '2026-08-05 02:24:22');
