INSERT INTO `events` (`id`, `title`, `slug`, `description`, `start_date`, `end_date`, `registration_deadline`, `location`, `address`, `event_type`, `event_status`, `featured_image`, `gallery_images`, `is_featured`, `is_visible`, `registration_link`, `speakers`, `organizer`, `contact_email`, `contact_phone`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(2, 'ICOSST 2026', 'icosst-2026', '19th International Conference on Open Source Systems and Technologies (ICOSST)\r\n\r\nICOSST is an international conference on Open Source Systems and Technologies, offering a platform for distributed enterprise computing and e-Governance etc. It highlights cost-effective development and deployment, focusing on innovative OSS approaches. ICOSST 2025 will be hybrid, allowing both virtual and in-person participation. Organized by Al-Khawarizmi Institute of Computer Science, UET Lahore and Department of Computer Science UET Lahore with IEEE’s technical co-sponsorship, it brings together global researchers to share ideas and advancements in Open Source systems and large-scale distributed frameworks. We welcome contributions in various areas related to Open Source systems', '2026-12-01 08:00:00', '2026-12-02 18:00:00', '2026-09-20 17:59:00', 'KICS UET', 'University of Engineering and Technology (UET), gt road, lahore.', 'conference', 'upcoming', 'events/featured/jczeTRMnhquW6bsSDIrC484b6OpDR24fCJAhlIF0.png', '[\"events/gallery/63jVgPsDfIRmgv5FUlgUvKtNz7t0HMaYaQOoPH1Z.png\"]', 0, 1, 'https://cmt3.research.microsoft.com/User/Login?ReturnUrl=%2FICOSST2026', NULL, 'Dr. Jamshaid Iqbal Janjua', 'icosst.secretariat@kics.edu.pk', NULL, 'ICOSST-2026', '19th International Conference on Open Source Systems and Technologies (ICOSST).\r\nICOSST is an international conference on Open Source Systems and Technologies, offering a platform for distributed enterprise computing and e-Governance etc. It highlights cost-effective development and deployment, focusing on innovative OSS approaches. ICOSST 2025 will be hybrid, allowing both virtual and in-person participation. Organized by Al-Khawarizmi Institute of Computer Science, UET Lahore and Department of Computer Science UET Lahore with IEEE’s technical co-sponsorship, it brings together global researchers to share ideas and advancements in Open Source systems and large-scale distributed frameworks. We welcome contributions in various areas related to Open Source systems', '2026-07-27 01:47:18', '2026-07-28 02:23:37');
