(300, 'SOFTNOS TECHNOLOGIES', 0, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Founder Name: <span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Fahad Miraj<strong style=\"mso-bidi-font-weight: normal;\"> <span style=\"mso-tab-count: 5;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Domain/Area: <span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;</span></span></strong>SEO/Internet Marketing <strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\"><span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Problem statement:<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong></p>\r\n<p class=\"MsoNormal\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Solution/Abstracts :</span></strong></p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: Cambria; mso-bidi-theme-font: major-latin;\">SoftNos Technologies is an innovative IT solutions provider. Softnos provides Digital Marketing, Web Applications and Mobile Applications services to a wide range of customers in all over the world. It offers a complete end to end product solution and user engagements to targeted markets. Softnos provides local support, quality and customer satisfaction in all aspects of digital marketing, SEO, Web Applications development,</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">USP: (Unique selling point)</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Potential Customers: </span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Companies</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Current Customers:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Monthly Sales: N/A</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Annually Sales: N/A</span></strong></p>', 'Softnos.png', 15, 0, 0, NULL, 'Startups', 0, NULL, 0),
(301, '99s', 0, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Founder Name: <span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Wajahat Anwar</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Domain/Area: <span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Times\',serif; mso-bidi-font-family: Times;\">Video Blog/ Vlogs/ Thought logs / Content Creator<strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Problem statement</span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">:<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><span style=\"mso-spacerun: yes;\">&nbsp;</span>Hi ! My Name is Wajahat and I want to talk about &ldquo;We&rdquo;. Want to</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">share your story not with me but with &ldquo;us&rdquo;. Let&rsquo;s talk. Let&rsquo;s make 99s video on &ldquo;us&rdquo;, &ldquo;we&rdquo;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">and &ldquo;our&rdquo; not &ldquo;I&rdquo;. Because true power lies in &ldquo;us&rdquo; not &ldquo;I&rdquo;. <strong style=\"mso-bidi-font-weight: normal;\"></strong></span></p>\r\n<p class=\"MsoNormal\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Solution/ Abstracts:<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong>Wajahat Anwar being a veteran programmer for one of startups has developed his pastime and hobby as an interesting startup.</p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\">He does Video Blogging as a medium for expression and all his videos captures the intrinsic beauty of daily life only in 99 seconds<strong style=\"mso-bidi-font-weight: normal;\"></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">USP: (Unique selling point)</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Business Model: (diagram)</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Potential Customers:</span></strong> <strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">People of Planet</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Current Customers: People of Planet</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Monthly Sales:<span style=\"mso-spacerun: yes;\">&nbsp;N/A</span></span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Annually Sales: N/A</span></strong></p>', '99.png', 15, 0, 0, NULL, 'Startups', 0, NULL, 0),
(302, 'PakVitae (AquaVitae) Solutions', 0, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Founder Name: </span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Shayan Sohail<strong style=\"mso-bidi-font-weight: normal;\"></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Domain/Area:&nbsp;</span></strong><span style=\"font-size: 11.5pt; line-height: 115%; mso-bidi-font-weight: bold;\">Water, Hardware/Health </span><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\"><span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Problem statement:<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Water Pollution&nbsp;</span><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\"><span style=\"mso-spacerun: yes;\">&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span><span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;</span></span></strong></p>\r\n<p class=\"Default\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 11.5pt; line-height: 115%;\"><strong>Solution:</strong> PakVitae provides life-time affordable filters that can purify water to 99.9999% without any power requirement. The company is currently working with NGOs, Government organizations, Army, educational and health institutes, and micro-entrepreneurs to bring clean affordable water to the people. The current target is Pakistani market via B2B sales for one year and then the company plans to launch the product in retail market. We are currently working on following solutions.</span><strong style=\"mso-bidi-font-weight: normal;\"></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">USP:&nbsp;</span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Nanotech based Filter very small in size and extremely low in cost</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Potential Customers:&nbsp;</span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">People from all the demographics, particuluarly the inhabitants of underprivillged areas forced to drink filthy water</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Achievments:&nbsp;</span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Won several international competitions and grants from donor bodies.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Have raised around $6.5 Million from Hashoo Group,&nbsp; followed up by another 7 figure round coinvested by another firm.</span></p>', 'shayanpakstraw.jpg', 15, 0, 0, NULL, 'Startups', 0, NULL, 0),
(303, 'Tech Tron ', 0, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Founder Name:<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Muneeb<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp; </span>Arif <strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-tab-count: 6;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Domain/Area: </span></strong><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Coding<strong style=\"mso-bidi-font-weight: normal;\"></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Opportunity :<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: Arial; color: #444444;\">What is really encouraging is that a majority of these are the initiatives of young professionals, who have studied from the prestigious universities in the USA etc or have given up their lucrative jobs and have returned, with the sole objective to make a name for Pakistan in the world of mobile game apps.&nbsp;</span><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\"><span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Solution: </span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify; line-height: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Trying to introduce a new era of mobile games we are working towards creation of creative and innovative mobile games. The game genres would generally include educational apps and games for kids and challenging strategy games for adults. The idea is to engage the user to spend their time usefully and creatively while challenging their mental acumen.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">USP: (Unique selling point)</span></strong><strong style=\"mso-bidi-font-weight: normal;\"></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Business Model:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Potential Customers: </span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Current Customers:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Monthly Sales</span></strong><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">:<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp; </span>60,000<strong style=\"mso-bidi-font-weight: normal;\"></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Annually Sales:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin;\">Team Members:<span style=\"mso-spacerun: yes;\">&nbsp; </span>8</span></strong></p>', 'TechTron.png', 15, 0, 0, NULL, 'Startups', 0, NULL, 0),
(304, 'Grandeur Technologies', 0, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Founder Name: </span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Moiz Husnain<strong style=\"mso-bidi-font-weight: normal;\"> </strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Domain/Area: </span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Internet of Things/AI<strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;&nbsp; </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Problem statement:<span style=\"mso-spacerun: yes;\">&nbsp; </span><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Today we all want to have smart home products in our homes because of the features of the products like you can save energy and you can use your appliances remotely, but even today these products are very costly and it is required that you will have to upgrade your appliances. Along with this, configuring currently available solutions are way more complex and it is required to make the process frictionless.<strong style=\"mso-bidi-font-weight: normal;\"></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Solution: <span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">To resolve this problem, we are coming up with our Smart Switch Board, through which you could make your home smart without upgrading your appliances and this comes with all the amazing features like energy monitoring, smart control and automation but at a pretty reduced price. So it is fast, it is efficient and it is cost effective. </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">USP: (Unique selling point): <span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">The traditional solutions are way more costly and it involves upgradation of appliances. We on the other hand are coming with a solution which is the most cost effective in the entire world (starting from Rs. 5000) through which multiple appliances can be made smart and along with this all it is fast and hence compatible with the internet speed that we have in our country which was never made for IoT.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Potential Customers:<span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">General Home Users</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Current Customers:<span style=\"mso-tab-count: 2;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Housing Societies and Building Constructors</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Monthly Sales:<span style=\"mso-tab-count: 2;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">NA<strong style=\"mso-bidi-font-weight: normal;\"> (</strong>Currently in Prototyping Mode)</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Annually Sales:<span style=\"mso-tab-count: 2;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">NA<strong style=\"mso-bidi-font-weight: normal;\"> (</strong>Currently in Prototyping Mode)<strong style=\"mso-bidi-font-weight: normal;\"></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Abstract:<span style=\"mso-spacerun: yes;\">&nbsp; </span><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%; font-family: \'Cambria\',serif; mso-ascii-theme-font: major-latin; mso-hansi-theme-font: major-latin; mso-bidi-font-family: \'Times New Roman\';\">Smart homes were once a fantasy and the topic of science fiction movies but recently we realized this dream of having a smart home by introducing smart products and home assistants, which involves the replacement of home appliances with new and upgraded ones and hence makes the overall cost of the system a lot. To resolve this problem we are coming up with our Smart Switch Board, through which upgradation of the appliances will no longer be required and you can make your home smart at a pretty less cost and it is fast and even compatible with 2G and it is secure as the data that flows through it is encrypted with industrial standard encryption algorithms.</span></p>', 'Moiz.jpg', 15, 0, 0, NULL, 'Startups', 0, NULL, 0),
(305, 'GLOBAL EVENTS & PR INC. (GEPRI)', 0, '<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Founder Name: </span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Bilal Ahmed &amp; Zeeshan <strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-tab-count: 4;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Domain/Area: <span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Photography, Events Coverage, Brand Launches and PR </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Problem statement:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Solution/Abstract:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Achievement: </span></strong><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 115%;\">Covers PSL in Dubai, Dubai Fashion Week for the last few years</span></p>\r\n<p class=\"MsoNormal\" style=\"text-ali