(226, 'Mr.AwaisAhmad', 297, 134, 3, 56, 'Mr.', 'Awais', 'Ahmad', 'awais.ahmad', 'awais.ahmad@kics.edu.pk', '+92-342-9029450', '832', '+923228013732', '', 'malePic.jpg', 0, '<p>Mr. Awais Ahmad got his Pre-Engineering from Punjab College of Science in 2009. He graduated from Department of Mechatronics and Control Engineering, University of Engineering and Technology, Lahore in 2013.&nbsp;</p>\r\n<p>He joined Al\' Khawarizmi Institute of Computer Science in July 2013 as Research Officer III. He is currently working on the project: Near Field Communication, a Simple and Fast Communication with Dr. Razi Iqbal.</p>\r\n<p>His research interests are in the field of Robotics, Embedded Systems, Software Systems, Wireless Technologies, Bio-medical Engineering and Entrepreneurship. &nbsp;&nbsp;</p>', '', 1, 0),
(227, 'musfara', 227, 134, 11, 56, 'Ms.', 'Musfara', 'Farooqui', '', 'musfara.farooqui@kics.edu.pk', '', '', '03350401675', '', 'MusfaraFarooqui2043', 0, '<p>Miss Musfara Farooqi has done her bachelor from UET Lahore in Electrical Engineering in 2012.</p>\r\n<p>She possesses one year teaching experience as Lecturer in University of Education, Township Campus Lahore</p>\r\n<p>She is currently working as a Research Officer in Alternate Energy and Research Inovation Lab, KICS</p>', '<p>Alternate Energy Systems</p>', 1, 0),
(230, 'abidkhan', 229, 16, 1, 85, 'Mr.', 'Muhammad  Abid ', 'Khan', '', 'abid.khan', '+92-42-99029450', '822', '0323-8661857', '+92-42-99250246', 'Muhammad  Abid Khan2070', 0, '<div class=\"gmail_default\" style=\"font-family: tahoma,sans-serif;\">Education: MBA (Finance) from University of the Punjab</div>\r\n<div class=\"gmail_default\" style=\"font-family: tahoma,sans-serif;\">Experience: Completed 3.5 Years&nbsp; C.A articles from a QCR rated Chartered Accountant firm in Lahore.</div>\r\n<div class=\"gmail_default\" style=\"font-family: tahoma,sans-serif;\">Lab: Administrative Sttaf<span><span style=\"color: #888888;\"><br clear=\"all\" /> </span></span></div>', '', 0, 0),
