(317, 'wajiha_ateeq', 320, 134, 11, 56, 'Ms.', 'Wajiha', 'Ateeq', '', 'wajiha.ateeq@kics.edu.pk', '', '', '', '', 'WajihaAteeq2853', 0, '', '', 1, 0),
(318, 'tashia_tayyab', 321, 134, 11, 56, 'Ms.', 'Tashia', 'Tayyab', '', 'tashia.tayyab@kics.edu.pk', '', '', '', '', 'TashiaTayyab2862', 0, '', '', 1, 0),
(319, 'muhammadfurqan_ijaz', 322, 134, 11, 56, 'Mr.', 'Muhammad Furqan', 'Ijaz', '', 'muhammadfurqaab.ijaz@kics.edu.pk', '', '', '', '', 'malePic.jpg', 0, '', '', 1, 0),
(320, 'ayesha_kamal', 323, 134, 11, 56, 'Ms.', 'Ayesha', 'Kamal', '', 'ayesha.kamal@kics.edu.pk', '', '', '', '', 'AyeshaKamal2880', 0, '<p>She has completed Chemical Engineering from PUnjab University (PU), Lahore. Currently, she is doing MS Engineering Management from University of Engineering and Technology, UET, Lahore. She is working as a research officer in Alernative Energy Research and Innovation Lab, Kics since 2015.&nbsp;</p>', '<p>Designing of biogas plant</p>\r\n<p>Solar Energy&nbsp;</p>\r\n<p>Solar system designing and installation&nbsp;</p>', 1, 0),
(321, 'Muhammad_Ali', 324, 131, 19, 17, 'Mr.', 'Muhammad ', 'Ali', '', 'm.ali', '', '', '', '', 'Muhammad Ali2889jpg', 0, '<p>Mr. Muhammad Ali, Manager EECL / IACL earned his Bachelors degree in Electrical Engineering from University of Engineering and Technology (UET) Lahore. He holds 17 plus years of experience in International industrial sector. He has worked with renowned oil and gas companies across Africa, Middle East and Pakistan. Attended various trainings courses in USA, Bahrain, South Africa, UAE, Nigeria, Korea and Japan. Earned many distinctions in his career including nomination for Chevron Diversity Ambassadorfor the Year 2009-2010. Presently he is managing Industrial automation and energy effcicency labs in KICS UET Lahore. He has performed multiple energy audits of various industrial brands as well as academic/health sector institutes</p>', '<p>Automation and Control</p>\r\n<p>Energy Efficiency and Conservation</p>\r\n<p>Energy Audidting</p>\r\n<p>Energy Montoring and Management</p>\r\n<p>Process Automation</p>\r\n<p>Motors and Generators</p>\r\n<p>Renewable Energy</p>', 0, 0),
(323, 'aqeelm_babar', 326, 16, 1, 119, 'Mr.', 'Aqeel M', 'Babar', '', 'aqeel.babar', '', '', '', '', 'Aqeel MBabar2907jpg', 0, '', '', 0, 0),
(324, 'sidra_akram', 327, 15, 1, 62, 'Ms.', 'Sidra ', 'Akram', '', 'sidra.akram@kics.edu.pk', '', '', '', '', 'Sidra Akram2916', 0, '<p>Sidra Akram has done MBA from University of the Punjab, Lahore. She is appointed as an HR Officer at Al-Khawarizmi Institute of Computer Science, UET.</p>', '', 1, 0),
(327, 'naveedyahya_hussain', 330, 136, 2, 116, 'Mr.', 'Naveed ', 'Yahya Hussain', '', 'naveed.yahya@kics.edu.pk', '', '', '', '', 'Naveed Yahya Hussain2943', 0, '<p>Naveed Yahya is a Research Officer at Al-Khuwarizmi Institute of Computer Science (KICS), U.E.T Lahore. He works on System design, Network design and Documentation of research projects.</p>\r\n<p>When he isn&rsquo;t glued to a computer screen, he spends time working in the garden, reading books, and playing soccer.</p>', '<p>Next Generation Networks (NGN)</p>\r\n<p>Security in Wireless/Wired Communications</p>\r\n<p>Software defined Networking</p>', 1, 0),
(328, 'hamza_hamid', 331, 136, 2, 74, 'Mr.', 'Hamza', 'Hamid', '', 'hamza.hamid@kics.edu.pk', '', '', '', '', 'malePic.jpg', 0, '', '', 1, 0),
(329, 'AbuBakar_Siddique', 332, 133, 5, 53, 'Mr.', 'Abu Bakar', 'Siddique', '', 'abubakar.siddique@kics.edu.pk', '42 99029450', '808', '', '', 'Abu BakarSiddique2961', 0, '<p>&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"font-size: 12.0pt; line-height: 115%; font-family: \'Times New Roman\',\'serif\'; color: black;\">Abu Bakar Siddique received his B.Sc. and M.Sc. degrees in electrical engineering from the University of Engineering and Technology Lahore, Pakistan, in 2006 and 2012, respectively. From January 2006 to February 2013, he had been working in Pakistan Telecommunication Company Limited (PTCL) as Operations Engineer in CDMA based Wireless Local Loop (WLL) network and served duties in the BSS, NSS, NOC, and IN departments. He was a faculty member in the Department of Electrical Engineering at University of Management and Technology (UMT) Lahore for two years. Currently he is a Senior Research Officer at Al-Khawrizmi Institute of&nbsp;Computer&nbsp;Science, University of Engineering and&nbsp;Technology Lahore. His current research interests include machine learning in acoustic domain, information and coding theory, optical and wireless communication networks.</span></p>', '<p>&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 8.05pt; line-height: normal; mso-outline-level: 1;\"><strong><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #283d4b; mso-font-kerning: 18.0pt;\">Publications:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: .0001pt; line-height: normal;\"><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\';\"><br /></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: .0001pt; line-height: normal;\"><strong><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #283d4b;\">Journal Papers</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 0in; text-indent: -.25in; line-height: 17.55pt; mso-list: l0 level1 lfo1; tab-stops: list .5in;\"><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\"><span style=\"mso-list: Ignore;\">1.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\">Siddique, A.B.; Tahir, M., &ldquo;<a href=\"http://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&amp;arnumber=6575087&amp;isnumber=6607129\" target=\"_blank\"><span style=\"color: #517551; text-decoration: none; text-underline: none;\">Joint Rate-Brightness Control using Variable Rate MPPM for LED Based Visible Light Communication Systems</span></a>,&rdquo;&nbsp;<em>Wireless Communications, IEEE Transactions on</em>&nbsp;, vol.12, no.9, pp.4604,4611, September 2013</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 0in; text-indent: -.25in; line-height: 17.55pt; mso-list: l0 level1 lfo1; tab-stops: list .5in;\"><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\"><span style=\"mso-list: Ignore;\">2.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\">Tahir, M.; Siddique, A.B., &ldquo;<a href=\"http://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&amp;arnumber=6197158&amp;isnumber=6238544\" target=\"_blank\"><span style=\"color: #517551; text-decoration: none; text-underline: none;\">Optimal Brightness-Rate Control using VR-MPPM and its Spectral Analysis for VLC System</span></a>,&rdquo;&nbsp;<em>Communications Letters, IEEE</em>&nbsp;, vol.16, no.7, pp.1125,1128, July 2012</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-top: 9.95pt; margin-right: 0in; margin-bottom: 9.95pt; margin-left: 0in; line-height: normal; mso-outline-level: 2;\"><strong><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #283d4b;\">Conference Papers</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 0in; text-indent: -.25in; line-height: 17.55pt; mso-list: l1 level1 lfo2; tab-stops: list .5in;\"><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\"><span style=\"mso-list: Ignore;\">1.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\">Siddique, Abu Bakar, and Muhammad Tahir. &ldquo;<a href=\"http://ieeexplore.ieee.org/xpls/abs_all.jsp?arnumber=7037125\" target=\"_blank\"><span style=\"color: #517551; text-decoration: none; text-underline: none;\">Bandwidth efficient multi-level MPPM encoding decoding algorithms for joint brightness-rate control in VLC systems</span></a>.&rdquo;&nbsp;<em>Global Communications Conference (GLOBECOM), 2014 IEEE</em>. IEEE, 2014.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 0in; text-indent: -.25in; line-height: 17.55pt; mso-list: l1 level1 lfo2; tab-stops: list .5in;\"><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\"><span style=\"mso-list: Ignore;\">2.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\">Siddique, Abu Bakar, and Muhammad Tahir. &ldquo;<a href=\"http://ieeexplore.ieee.org/xpls/abs_all.jsp?arnumber=6952041\" target=\"_blank\"><span style=\"color: #517551; text-decoration: none; text-underline: none;\">Joint error-brightness control coding for LED based VLC link</span></a>.&rdquo;&nbsp;<em>Wireless Communications and Networking Conference (WCNC), 2014 IEEE</em>. IEEE, 2014.</span></p>\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; margin-left: 0in; text-indent: -.25in; line-height: 17.55pt; mso-list: l1 level1 lfo2; tab-stops: list .5in;\"><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\"><span style=\"mso-list: Ignore;\">3.<span style=\"font: 7.0pt \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\'; mso-fareast-font-family: \'Times New Roman\'; color: #444444;\">Siddique, A.B.; Tahir, M., &ldquo;<a href=\"http://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&amp;arnumber=5766321&amp;isnumber=5766312\" target=\"_blank\"><span style=\"color: #517551; text-decoration: none; text-underline: none;\">Joint brightness control and data transmission for visible light communication systems based on white LEDs</span></a>,&rdquo;&nbsp;<em>Consumer Communications and Networking Conference (CCNC), 2011 IEEE</em>&nbsp;, vol., no., pp.1026,1030, 9-12 Jan. 2011</span></p>', 1, 0),
