(442, 'ali_muzaffar', 463, 132, 0, 38, 'Mr.', 'Ali', 'Muzaffar', '', 'ali.muzaffar', '', '', '0321 4887677', '', 'AliMuzaffar3978jpg', 0, '', '', 0, 0),
(443, 'www.facebook.com/mini.zain.58', 464, 134, 0, 54, 'Mr.', 'Muhammad', 'Ali Ibrahim', '', 'ali.ibrahim@kics.edu.pk', '', '', '+92 307 7766966', '', 'MuhammadAli Ibrahim3987jpg', 7, '<p>Mr Muhammad Ali Ibrahim, a research officer, joined KICS in September 2017 after completing his graduation with distinction. Over the period, he has worked over different projects such as Semantic Engine for Urdu Text Management using Ontology and Knowledge Engineering (SETMOKE) which include following six modules for Urdu language: Stemming, Pos-Tagging, Named Entity Recognition, Text summarization, Text Classification, Question Classification, and Information Retrieval,&nbsp; Biomedical Query expansion, Ontology learning from unstructured texts, and Multi-Label Text classification.</p>', '<p>Feature engineering, Classification, Active Learning, Ontology Learning, Knowledge Discovery, Recommendation system, and Fraud Detection</p>', 1, 0),
(451, 'mustafa_arshad', 466, 134, 0, 56, 'Mr.', 'Syed Mustafa', 'Arshad', '', 'mustafa.arshad@kics.edu.pk', '', '', '+92 331 4368914', '', 'Syed MustafaArshad4059', 4, '<p><span style=\"font-size: small;\">Mr. Syed Mustafa Arshad completed his graduation from University of Engineering and Technology, Lahore in 2017 in the discipline of Electrical Engineering with major in Computer.&nbsp;</span></p>\r\n<p><span style=\"font-size: small;\">He is currently working as Research Officer in Data Sciences Lab.</span></p>', '<ul>\r\n<li><span style=\"font-size: small;\">Data Sciences</span></li>\r\n<li><span style=\"font-size: small;\">Programming</span></li>\r\n<li><span style=\"font-size: small;\">Quality Assurance</span></li>\r\n</ul>', 1, 0),
(452, 'hafiza_mahnoor', 467, 134, 0, 54, 'Ms.', 'Hafiza Mahnoor', 'Abbasi', '', 'mahnoor.abbasi@kics.edu.pk', '', '', '+92 334 4338264', '', 'Hafiza MahnoorAbbasi4068', 6, '<p><span style=\"font-size: medium;\">Mahnoor Abbasi has graduated from UET Lahore in Electrical Engineering (Computer). She is currently pursuing her master</span><span style=\"font-size: medium;\">&nbsp;degree in Computer Science from UET Lahore.</span></p>', '<ul>\r\n<li><span style=\"font-size: medium;\">Data Sciences</span></li>\r\n<li><span style=\"font-size: medium;\">Networks and Security</span></li>\r\n</ul>', 1, 0),
(453, 'zahra_zulfiqar', 468, 134, 0, 54, 'Ms.', 'Zahra', 'Zulfiqar', '', 'zahra.zulfiqar@kics.edu.pk', '', '', '+92 324 6505175', '', 'ZahraZulfiqar4077', 5, '<p><span style=\"font-size: small;\">Zahra Zulfiqar is&nbsp;working as a Research Officer in data sciences lab. She has done her graduation in Electrical engineering from UET Lahore in 2017. She is currently enrolled in Masters program(Computer Science department) of UET Lahore.&nbsp;</span></p>', '<ul>\r\n<li><span style=\"font-size: small;\">Machine learning</span></li>\r\n<li><span style=\"font-size: small;\">Artificial intelligence</span></li>\r\n<li><span style=\"font-size: small;\">Data mining&nbsp;</span></li>\r\n</ul>', 1, 0),
(457, 'nauman_hanif', 470, 134, 0, 54, 'Mr.', 'Muhammad Nauman', 'Hanif', '', 'nauman.hanif', '0429929450', '837', '+923214946496', '', 'Muhammad NaumanHanif4113jpg', 0, '<p>I have done Master in Information Technology from BZU Multan.</p>\r\n<p>Currently, I am employee at Al-khwarizmi Institute of Computer Science as Research Officer.</p>', '<ul>\r\n<li>HTML 5</li>\r\n<li>Bootstrap 3</li>\r\n<li>CSS and CSS3</li>\r\n<li>Php and Mysql</li>\r\n<li>JQuery (lastest)</li>\r\n<li>Java Scripting</li>\r\n<li>Opencms</li>\r\n<li>.NET(Desktop Application)</li>\r\n<li>Wordpress</li>\r\n<li>Web technologies</li>\r\n<li>Databases</li>\r\n<li>ERPs</li>\r\n<li>Designing in Adobe Photoshop</li>\r\n</ul>', 0, 0),
