(528, 'basim_afzal', 549, 134, 0, 54, 'Mr.', 'Basim', 'Afzal', '', 'basim.afzal@kics.edu.pk', '', '', '', '', 'BasimAfzal4752jpg', 0, '', '', 1, 0),
(529, 'ahmad_hussain1122', 550, 134, 0, 54, 'Mr.', 'Ahmad', 'Hussain Safder', '', 'ahmad.hussain@kics.edu.pk', '99029450', '838', '0346-4645049', '', 'AhmadHussain Safder4761jpg', 0, '<p>Ahmad Hussain Safder was born in Lahore, Pakistan in 1994. He received B.Sc. degree in Electrical Engineering from COMSATS University Islamabad, Lahore Campus. Currently, he is pursuing his M.Sc. in Electrical Engineering (Control Systems) from UET Lahore.</p>\r\n<p>He joined Al-Khwarizmi Institute of Computer Science, UET Lahore as Research Officer on 1 st November 2017. His research area is Electric vehicle drive design and power generation by renewable sources.</p>', '<p>Control System</p>\r\n<p>Power Converters</p>\r\n<p>Embedded Control</p>\r\n<p>Machine Drives Design</p>\r\n<p>Renewable Power Resources&nbsp;</p>\r\n<p>PIC Controller Coding (Assembly &amp; C)</p>\r\n<p>MATLAB</p>\r\n<p>LabVIEW</p>', 1, 0),
(530, 'Salman_Arshad', 551, 134, 0, 114, 'Mr.', 'Salman', 'Arshad', '', 'Salman.Arshad@kics.edu.pk', '', '', '', '', 'malePic.jpg', 0, '', '', 1, 0),
