(557, 'ghazanfar_abbas', 576, 132, 0, 38, 'Mr.', ' Syed Ghazanfar', 'Abbas', '', 'ghazanfar.abbas@kics.edu.pk', '', '', '', '', ' Syed GhazanfarAbbas5013jpg', 0, '<p class=\"MsoBodyText\" style=\"margin-top: 2.0pt; margin-right: 0in; margin-bottom: 6.0pt; margin-left: 0in; line-height: normal;\">Syed Ghazanfar Abbas is Sr. Research Associate / Team Lead in IoT Security, developing developing smart home and campus&nbsp; Solutions embedded with Machine learning and Deep Learning. His overall software development experience is 10+ years and worked on number of projects/products; Customer Management System (CMS), Call Center Applications, Point of Sale (PoS), Financial Systems and News Production System (replica of ENPS). Ghazanfar Abbas is a Microsoft Certified Professional Developer (MCPD). He received his Master of Computer Science degree from National University of Computer &amp; Emerging Sciences. For the Last 3 years he is actively working in Research &amp; Development of Interent of Things (IoT) and developed Smart Home IoT Firewall (ThingzFirewall), open source IoT Testbed (IoT-Flock) and published number of research items.</p>', '<p>Internet of Things, Machine Learning, Software Development, Database Management</p>', 1, 0),
(558, 'usman_gulzar', 577, 133, 0, 53, 'Mr.', 'Usman', 'Gulzar', '', 'usman.gulzar@kics.edu.pk', '', '', '', '', 'UsmanGulzar5022jpg', 0, '<div>4.5 year of experience in middleware application development, penetration testing/Security Audit, read teaming and forensic/hacking research.</div>', '', 1, 0),
(559, 'asim_tanwir', 578, 134, 0, 54, 'Mr.', 'Asim', 'Tanwir', '', 'asim.tanwir@kics.edu.pk', '', '', '0323-8820016', '', 'AsimTanwir5031jpg', 0, '<p>Holds MS degree in Computer Sciences from University of Agriculture, Faisalabad and BS</p>\r\n<p>degree in Electrical (Telecom) Engineering from GC University, Faisalabad.</p>', '<p>Internet of Everything (IoE), Cognitive Radio IoT (CRIoT), Wireless Communication,</p>\r\n<p>Embedded Network Security and Penetration Testing.</p>', 1, 0),
